  rawRouteRefreshAt = now;
  let rows = suppliedRows;
  if (!Array.isArray(rows)) {
    if (!fs.existsSync(DB_FILE)) return false;
    rows = dbSelect("SELECT id, remark, protocol, port, enable, settings, stream_settings FROM inbounds WHERE protocol IN ('vless','vmess','trojan','mtproto','shadowsocks') ORDER BY id;");
  }
  if (!Array.isArray(rows)) return false;
  const signature = crypto.createHash("sha256").update(rows.map((row) => [
    rowValue(row, ["id"]), rowValue(row, ["remark"]), rowValue(row, ["protocol"]),
    rowValue(row, ["port"]), rowValue(row, ["enable"]), rowValue(row, ["settings"]),
    rowValue(row, ["stream_settings", "streamSettings"]),
  ].map((x) => String(x == null ? "" : x)).join("\u001f")).join("\n")).digest("hex");
