// `lang` cookie and the subscription-page language from the `subLang`
// cookie (each falling back to the browser language, then en-US). The
// proxy presets each cookie only when the visitor has not chosen one yet,
// so a deliberate choice via either language selector is always kept.
const PANEL_DEFAULT_LANGUAGE = "en-US";
// The message that replaces the configs of a disabled user inside an app.
const APP_DISABLED_LANGUAGE = "fa";
const INACTIVE_NODE_PREFIX = "vless://00000000-0000-0000-0000-000000000000@127.0.0.1:1?";

function pluralSlavic(n, one, few, many) {
  const m10 = n % 10;
  const m100 = n % 100;
  if (m10 === 1 && m100 !== 11) return one;
  if (m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14)) return few;
  return many;
}

function pluralArabic(n, one, two, few, many) {
  const m100 = n % 100;
  if (n === 1) return one;
  if (n === 2) return two;
  if (m100 >= 3 && m100 <= 10) return few;
  return many;
}

