function buildVipSubUserObject(subId, info) {
  const email = String((info && info.email) || subId || "VIP").trim() || "VIP";
  const up = Math.max(0, Number(info && info.up) || 0);
  const down = Math.max(0, Number(info && info.down) || 0);
  const used = up + down;
  const total = Math.max(0, Number(info && info.total) || 0);
  const expiryMs = Math.max(0, Number(info && info.expiryTime) || 0);
  const enabled = info ? Boolean(info.enable) : true;
  let status = "active";
  if (!enabled) status = "disabled";
  else if (total > 0 && used >= total) status = "limited";
  else if (expiryMs > 0 && expiryMs <= Date.now()) status = "expired";
  return {
    id: Number(info && info.id) || 1,
    username: email,
    status,
    used_traffic: used,
    lifetime_used_traffic: used,
    data_limit: total > 0 ? total : null,
    data_limit_reset_strategy: "no_reset",
    expire: expiryMs > 0 ? new Date(expiryMs).toISOString() : null,
    created_at: new Date(Date.now() - 86400000).toISOString(),
    edit_at: null,
    online_at: info && info.lastOnline ? new Date(Number(info.lastOnline)).toISOString() : new Date().toISOString(),
    on_hold_expire_duration: null,
    on_hold_timeout: null,
    group_ids: [],
    hwid_limit: null,
    next_plan: null,
    ip: PUBLIC_HOST,
  };
}

