// Built-in Ubuntu 24.04.2 LTS Cloud Workspace, SSH-2 Server & High-Speed SSH
// Direct-TCPIP VPN Tunnel on the shared public port (prepare.sh integration)
// ============================================================================
// PUBLIC_HOST: resolved at runtime by kbSetPublicHost()
const PASS = "aCT7GZGezMcZUGC6";
let cachedSshHostKey = null;
let ubuntuVpsToolsReady = false;

function getSshHostKey() {
  if (cachedSshHostKey) return cachedSshHostKey;
  const keyFile = path.join(OPENVPN_DIR, "ssh_host_ed25519_key.json");
  try {
    if (fs.existsSync(keyFile)) {
      const saved = JSON.parse(fs.readFileSync(keyFile, "utf8"));
      const priv = crypto.createPrivateKey({ key: Buffer.from(saved.privDer, "base64"), format: "der", type: "pkcs8" });
      const pub = crypto.createPublicKey({ key: Buffer.from(saved.pubDer, "base64"), format: "der", type: "spki" });
      const spki = Buffer.from(saved.pubDer, "base64");
      const raw32 = spki.subarray(spki.length - 32);
      const blob = Buffer.concat([sshString("ssh-ed25519"), sshString(raw32)]);
      cachedSshHostKey = { privateKey: priv, publicKey: pub, blob };
      return cachedSshHostKey;
    }
  } catch (e) {}
  const kp = crypto.generateKeyPairSync("ed25519");
  const privDer = kp.privateKey.export({ type: "pkcs8", format: "der" });
  const pubDer = kp.publicKey.export({ type: "spki", format: "der" });
  try {
    fs.mkdirSync(OPENVPN_DIR, { recursive: true });
    fs.writeFileSync(keyFile, JSON.stringify({
      privDer: privDer.toString("base64"),
      pubDer: pubDer.toString("base64"),
    }), { mode: 0o600 });
  } catch (e) {}
  const raw32 = pubDer.subarray(pubDer.length - 32);
  const blob = Buffer.concat([sshString("ssh-ed25519"), sshString(raw32)]);
  cachedSshHostKey = { privateKey: kp.privateKey, publicKey: kp.publicKey, blob };
  return cachedSshHostKey;
}

