      if (!panelOriginRequestAllowed(socket, buf)) {socket.end(browserDnsErrorRedirect());return;}
      if (nativePasarGuardRoute(socket, buf)) return;
      if (kbAdminChartRoute(socket, buf)) return;
      let reqPath = requestPath(buf);
      { const aliasBuf = normalizeSubAliasTarget(buf); if (aliasBuf) { buf = aliasBuf; reqPath = requestPath(buf); } }
      if (reqPath.startsWith(BASE + "/vps") && serveVpsDashboardRequest(socket, buf)) {
        return;
      }
      const wgConfSubId = wireguardConfigSubId(reqPath);
      if (wgConfSubId) {
        Promise.resolve(wireguardConfigHttpResponse(buf, wgConfSubId, dbFile))
          .then((response) => { if (!socket.destroyed) socket.end(response); })
          .catch(() => socket.destroy());
        return;
      }
      const amneziaConfSubId = amneziaWGConfigSubId(reqPath);
      if (amneziaConfSubId) {
        Promise.resolve(amneziaWGConfigHttpResponse(buf, amneziaConfSubId, dbFile))
          .then((response) => { if (!socket.destroyed) socket.end(response); })
          .catch(() => socket.destroy());
        return;
      }
      const openVpnConfSubId = openVpnConfigSubId(reqPath);
      if (openVpnConfSubId) {
        socket.end(openVpnConfigHttpResponse(buf, openVpnConfSubId, dbFile, openVpnProfileResolver));
        return;
      }

      // Stable per-subscription WebSocket/HTTPUpgrade aliases use an HMAC path,
      // then rewrite only the HTTP request target to the configured inbound path.
      const uniqueRoute = uniqueWsPathRoutes.get(reqPath);
      if (uniqueRoute) {
        const method = buf.toString("latin1").split(/\r?\n/, 1)[0].split(/\s+/, 1)[0].toUpperCase();
        const requestHeaders = requestHeaderMap(buf);
        if (method !== "GET" || !/websocket/i.test(requestHeaders.upgrade || "")) {
          socket.end(notFoundPage());
          return;
        }
        const originalTarget = requestTarget(buf);
        const queryAt = originalTarget.indexOf("?");
        const query = queryAt >= 0 ? originalTarget.slice(queryAt) : "";
        const internalPath = String(uniqueRoute.internalPath || "");
        const separator = query && internalPath.includes("?") ? "&" : "";
        const rewritten = rewriteRequestTarget(buf, internalPath + separator + query);
        if (!rewritten) {
          socket.end(notFoundPage());
          return;
        }
        socket.pause();
        splice(socket, uniqueRoute.port, rewritten);
        return;
      }

      // 1. VPN WebSocket / HTTPUpgrade endpoints
      for (const prefix of Object.keys(PATHS)) {
        if (reqPath === prefix || reqPath.startsWith(prefix + "/")) {
          socket.pause();
          splice(socket, PATHS[prefix], buf);
          return;
        }
      }

      // The JSON and Clash subscription outputs are disabled on purpose; they
      // must not exist on the public port, so they get the same black 404 as
      // any unknown path.
      if (reqPath === "/json" || reqPath.startsWith("/json/")
        || reqPath === "/clash" || reqPath.startsWith("/clash/")) {
        socket.end(notFoundPage());
        return;
      }

      // 2. Native official subscription routes, loopback listener only.
      if (isNativeSubRequestPath(reqPath)) {
        if (process.env.SELFTEST !== "1") {
          const remoteIp = remoteAddressOf(socket);
          const isLoopback = remoteIp === "127.0.0.1" || remoteIp === "::1" || remoteIp === "::ffff:127.0.0.1";
          const hdrMap = requestHeaderMap(buf);
          const reqHost = String(hdrMap["x-sub-host"] || hdrMap.host || "").toLowerCase().trim();
          const bareHost = reqHost.split(":")[0];
          const isDirectSublink = reqPath.startsWith("/sublink/") || reqPath.startsWith("/sub/");
          if (!isLoopback && !isDirectSublink && (bareHost === PUBLIC_HOST || (state.publicHost && bareHost === String(state.publicHost).toLowerCase()) || !reqHost.endsWith(":8443") || reqPath === "/sub" || reqPath.startsWith("/sub/"))) {
            socket.end(browserDnsErrorRedirect());
            return;
          }
        }
        socket.pause();
        forwardNativeSubscription(socket, buf, PORTS.sub);
        return;
      }

      // 3. Strict Panel path check:
      // MUST start with BASE + "/" e.g. "/TeamGuccI/"
      // If reqPath is "/TeamGuccI" (missing trailing slash) or anything else -> 404 BLACK PAGE!
      // Auto-rewrite un-prefixed "/panel/" requests so all native UI AJAX calls succeed seamlessly
      if (reqPath.startsWith("/panel/")) {
        const rewritten = rewriteRequestTarget(buf, BASE + requestTarget(buf));
        if (rewritten) {
          buf = rewritten;
          reqPath = BASE + reqPath;
        }
      }
      // Auto-rewrite un-prefixed "/panel/" requests so all native UI AJAX calls succeed seamlessly
      if (reqPath.startsWith("/panel/")) {
        const rewritten = rewriteRequestTarget(buf, BASE + requestTarget(buf));
        if (rewritten) {
          buf = rewritten;
          reqPath = BASE + reqPath;
        }
      }
      if (reqPath.startsWith(BASE + "/")) {
        const pgAsset = pasarGuardAsset(buf);
        if (pgAsset) { socket.end(pgAsset); return; }
        const asset = brandAsset(buf);
        if (asset) {
          socket.end(asset);
          return;
        }
        if (!state.ready) {
          socket.end(statusPage());
          return;
        }
        socket.pause();
        brandProxy(socket, buf);
        return;
      }

      // Additional TLS/WebSocket wrappers terminate only framing, then feed
      // the existing VMess and Trojan inbounds (same users and quotas).
