  const size = Math.trunc(Number(outLen) || 32);
  if (size < 1 || size > 32 || secret.length > 32) throw new Error("invalid BLAKE2s parameters");
  const h = BLAKE2S_IV.slice();
  h[0] = (h[0] ^ 0x01010000 ^ (secret.length << 8) ^ size) >>> 0;
  const v = new Array(16);
