  assert(recommendedGoProcs(512 * 1024 * 1024, 8, 8) === 1, "low-memory Go cap");
  assert(recommendedGoProcs(2 * 1024 * 1024 * 1024, 8, 3) === 3, "Go workers respect CPU quota");
  assert(recommendedGoProcs(4 * 1024 * 1024 * 1024, 32, 0) === 8, "Go worker cap");
  assert(isPublicIp("8.8.8.8") && isPublicIp("1.1.1.1"), "public IP detection");
  assert(publicBaseUrl("51.75.118.149") === publicScheme() + "://51.75.118.149:" + PUBLIC_PORT,
    "public panel and subscription URLs use the edge scheme on the allocated port");
  assert(PUBLIC_TLS && publicScheme() === "https", "the public edge terminates TLS in-process by default");
