  assert(pickPort(Buffer.from("GET /bp-vless?x=1 HTTP/1.1\r\n")) === PANEL_PORT, "legacy path route is disabled");
  assert(pickPort(Buffer.from("PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n")) === PORTS.vless, "gRPC path transport is disabled");
