// Stability diagnostic: no packet or credential logging.
if (process.env.SELFTEST !== "1") {
  try {
    const lag = require("node:perf_hooks").monitorEventLoopDelay({ resolution: 20 });
    lag.enable();
    setInterval(() => {
      const ms = Math.round(lag.max / 1e6);
      if (ms > 250) log("[stability] event-loop max delay=" + ms + "ms in last 30s");
      lag.reset();
    }, 30000).unref();
  } catch (_) {}
}

// Bounded resource diagnostics for the constrained host.
if (process.env.SELFTEST !== "1") {
  const resourceTimer = setInterval(() => {
    try {
      const m = process.memoryUsage();
      log("[resources] node rssMiB=" + (m.rss/1048576).toFixed(1) + " heapMiB=" + (m.heapUsed/1048576).toFixed(1) + " externalMiB=" + (m.external/1048576).toFixed(1));
    } catch (_) {}
  }, 300000);
  resourceTimer.unref();
  setTimeout(() => { const m=process.memoryUsage(); log("[resources] boot rssMiB="+(m.rss/1048576).toFixed(1)+" heapMiB="+(m.heapUsed/1048576).toFixed(1)); }, 90000).unref();
}

// One-shot external network probe (L2TP/IKEv2 feasibility), enabled by data/netprobe.json {"on":true}.
if (process.env.SELFTEST !== "1") {
  try {
    const npFlag = path.join(DATA, "netprobe.json");
    let npOn = false;
    if (fs.existsSync(npFlag)) {
      try { npOn = !!JSON.parse(fs.readFileSync(npFlag, "utf8") || "{}").on; } catch (e) {}
    }
    if (npOn) {
      const probe = require("dgram");
      const cpProbe = require("child_process");
      const npRes = path.join(DATA, "netprobe-result.json");
      const npOut = { startedAt: new Date().toISOString(), ports: {}, packets: [], caps: {}, devices: {}, xfrm: null, bins: [] };
      const npSave = () => { try { fs.writeFileSync(npRes, JSON.stringify(npOut, null, 1)); } catch (e) {} };
      try {
        const st = fs.readFileSync("/proc/self/status", "utf8");
        const mm = st.match(/CapEff:\s*([0-9a-f]+)/i);
        if (mm) {
          const v = BigInt("0x" + mm[1]);
          const has = (b) => ((v >> BigInt(b)) & 1n) === 1n;
          npOut.caps = { CapEff: mm[1], NET_BIND_SERVICE: has(10), NET_ADMIN: has(12), NET_RAW: has(13), SYS_MODULE: has(16), SYS_ADMIN: has(21) };
        }
      } catch (e) { npOut.capsErr = String(e.message); }
      for (const d of ["/dev/net/tun", "/dev/ppp", "/proc/net/xfrm_stat", "/proc/net/pppol2tp", "/proc/net/l2tp", "/sys/module/l2tp_ppp", "/sys/module/ppp_generic", "/sys/module/esp4", "/sys/module/xfrm_user"]) {
        npOut.devices[d] = fs.existsSync(d);
      }
      try { npOut.xfrm = String(cpProbe.execSync("ip xfrm state 2>&1 || true", { timeout: 5000 })).trim() || "(empty)"; } catch (e) { npOut.xfrm = "ERR " + e.message; }
      try { npOut.bins = fs.readdirSync(BIN_DIR).filter((f) => /ipsec|strongswan|charon|xl2tpd|ocserv|pppd|sstp|accel|vpn/i.test(f)); } catch (e) { npOut.bins = ["ERR " + e.message]; }
      for (const pp of [500, 4500, 1701, 20357]) {
        const so = probe.createSocket("udp4");
        so.on("error", (e) => { npOut.ports[pp] = "bind-error " + (e.code || e.message); npSave(); });
        so.on("message", (msg, rinfo) => {
          npOut.packets.push({ port: pp, from: rinfo.address + ":" + rinfo.port, len: msg.length, head: msg.slice(0, 12).toString("hex"), at: new Date().toISOString() });
          try { so.send(Buffer.from("NETPROBE-PONG-" + pp), rinfo.port, rinfo.address); } catch (e) {}
          npSave();
        });
        so.bind(pp, "0.0.0.0", () => { npOut.ports[pp] = "listening"; npSave(); });
        const tt = setTimeout(() => { try { so.close(); } catch (e) {} npOut.ports[pp] = "closed-after-ttl"; npSave(); }, 15 * 60 * 1000);
        if (tt.unref) tt.unref();
      }
      npSave();
      log("[netprobe] listening on 500/4500/1701/20357");
    }
  } catch (e) { log("[netprobe] failed: " + e.message); }
}

// One-shot egress speed probe, enabled by data/speedprobe.json {"on":true}.
if (process.env.SELFTEST !== "1") {
  try {
    const spFlag = path.join(DATA, "speedprobe.json");
    let spOn = false;
    if (fs.existsSync(spFlag)) { try { spOn = !!JSON.parse(fs.readFileSync(spFlag, "utf8") || "{}").on; } catch (e) {} }
    if (spOn) {
      const https = require("https");
      const spRes = path.join(DATA, "speedprobe-result.json");
      const spOut = { startedAt: new Date().toISOString(), runs: [], env: {} };
      const spSave = () => { try { fs.writeFileSync(spRes, JSON.stringify(spOut, null, 1)); } catch (e) {} };
      try {
        const cpuinfo = fs.readFileSync("/proc/cpuinfo", "utf8");
        spOut.env.aes = /\baes\b/.test(cpuinfo);
        spOut.env.cores = (cpuinfo.match(/^processor\s*:/gm) || []).length;
        spOut.env.model = (cpuinfo.match(/model name\s*:\s*(.*)/) || [])[1] || "?";
      } catch (e) {}
      for (const f of ["/sys/fs/cgroup/cpu.max", "/sys/fs/cgroup/cpu/cpu.cfs_quota_us", "/sys/fs/cgroup/memory.max", "/sys/fs/cgroup/memory/memory.limit_in_bytes"]) {
        try { spOut.env[path.basename(f)] = fs.readFileSync(f, "utf8").trim(); } catch (e) {}
      }
      const one = (bytes, label) => new Promise((resolve) => {
        const started = Date.now();
        let got = 0, done = false;
        const finish = (err) => { if (done) return; done = true; const dt = (Date.now() - started) / 1000;
          spOut.runs.push({ label, bytes: got, seconds: +dt.toFixed(2), kBps: dt > 0 ? Math.round(got / 1024 / dt) : 0, error: err || null, at: new Date().toISOString() });
          spSave(); resolve(); };
        const req = https.get("https://speed.cloudflare.com/__down?bytes=" + bytes, { timeout: 25000 }, (res) => {
          if (res.statusCode !== 200) { res.resume(); return finish("http " + res.statusCode); }
          res.on("data", (c) => { got += c.length; });
          res.on("end", () => finish(null));
          res.on("error", (e) => finish(e.message));
        });
        req.on("timeout", () => { try { req.destroy(); } catch (e) {} finish("timeout"); });
        req.on("error", (e) => finish(e.message));
        setTimeout(() => { try { req.destroy(); } catch (e) {} finish("deadline"); }, 30000).unref();
      });
      (async () => {
        await one(10000000, "10MB-cloudflare");
        await one(50000000, "50MB-cloudflare");
        await one(10000000, "10MB-cloudflare-2nd");
        spOut.finishedAt = new Date().toISOString();
        spSave();
        log("[speedprobe] done");
      })();
      log("[speedprobe] started");
    }
  } catch (e) { log("[speedprobe] failed: " + e.message); }
}

// One-shot outbound latency probe, enabled by data/latprobe.json {"on":true}.
if (process.env.SELFTEST !== "1") {
  try {
    const lpFlag = path.join(DATA, "latprobe.json");
    let lpOn = false;
    if (fs.existsSync(lpFlag)) { try { lpOn = !!JSON.parse(fs.readFileSync(lpFlag, "utf8") || "{}").on; } catch (e) {} }
    if (lpOn) {
      const dgram2 = require("dgram");
      const net2 = require("net");
      const cr2 = require("crypto");
      const lpRes = path.join(DATA, "latprobe-result.json");
      const lpOut = { startedAt: new Date().toISOString(), probes: {} };
      const lpSave = () => { try { fs.writeFileSync(lpRes, JSON.stringify(lpOut, null, 1)); } catch (e) {} };
      const stat = (arr) => {
        if (!arr.length) return {};
        const s2 = arr.slice().sort((a, b) => a - b);
        const avg = arr.reduce((a, b) => a + b, 0) / arr.length;
        const mdev = Math.sqrt(arr.reduce((a, b) => a + (b - avg) * (b - avg), 0) / arr.length);
        return { n: arr.length, min: +s2[0].toFixed(1), p50: +s2[Math.floor(s2.length / 2)].toFixed(1), avg: +avg.toFixed(1), max: +s2[s2.length - 1].toFixed(1), mdev: +mdev.toFixed(1) };
      };
      const udpRtt = (ip, port, payload, samples) => new Promise((resolve) => {
        const lat = []; let i = 0, lost = 0;
        const sock = dgram2.createSocket("udp4");
        const next = () => {
          if (i >= samples) { try { sock.close(); } catch (e) {} lpOut.probes[ip + ":" + port] = Object.assign({ loss: lost }, stat(lat)); lpSave(); return resolve(); }
          i++;
          const t0 = process.hrtime.bigint();
          let done = false;
          const onMsg = () => { if (done) return; done = true; sock.removeListener("message", onMsg); lat.push(Number(process.hrtime.bigint() - t0) / 1e6); setTimeout(next, 60); };
          sock.once("message", onMsg);
          setTimeout(() => { if (!done) { done = true; sock.removeListener("message", onMsg); lost++; setTimeout(next, 60); } }, 1500);
          try { sock.send(payload, port, ip); } catch (e) { lost++; setTimeout(next, 60); }
        };
        next();
      });
      const tcpRtt = (host, port, samples) => new Promise((resolve) => {
        const lat = []; let i = 0, lost = 0;
        const next = () => {
          if (i >= samples) { lpOut.probes["tcp:" + host + ":" + port] = Object.assign({ loss: lost }, stat(lat)); lpSave(); return resolve(); }
          i++;
          const t0 = process.hrtime.bigint();
          const s3 = net2.connect({ host, port, family: 4 });
          let done = false;
          s3.setTimeout(2000);
          s3.on("connect", () => { done = true; lat.push(Number(process.hrtime.bigint() - t0) / 1e6); s3.destroy(); setTimeout(next, 60); });
          const fail = () => { if (done) return; done = true; lost++; try { s3.destroy(); } catch (e) {} setTimeout(next, 60); };
          s3.on("error", fail); s3.on("timeout", fail);
        };
        next();
      });
      (async () => {
        const stun = Buffer.concat([Buffer.from([0x00, 0x01, 0x00, 0x00, 0x21, 0x12, 0xa4, 0x42]), cr2.randomBytes(12)]);
        const dnsq = Buffer.concat([Buffer.from([0xab, 0xcd, 0x01, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00]), Buffer.from([0x07]), Buffer.from("example"), Buffer.from([0x03]), Buffer.from("com"), Buffer.from([0x00, 0x00, 0x01, 0x00, 0x01])]);
        await udpRtt("1.1.1.1", 53, dnsq, 15);
        await udpRtt("8.8.8.8", 53, dnsq, 15);
        await tcpRtt("1.1.1.1", 443, 10);
        await tcpRtt("8.8.8.8", 443, 10);
        lpOut.finishedAt = new Date().toISOString();
        lpSave();
        log("[latprobe] done");
      })();
      log("[latprobe] started");
    }
  } catch (e) { log("[latprobe] failed: " + e.message); }
}

// One-shot health probe (cgroup CPU throttling + per-process CPU), data/healthprobe.json {"on":true}.
if (process.env.SELFTEST !== "1") {
  try {
    const hpFlag = path.join(DATA, "healthprobe.json");
    let hpOn = false;
    if (fs.existsSync(hpFlag)) { try { hpOn = !!JSON.parse(fs.readFileSync(hpFlag, "utf8") || "{}").on; } catch (e) {} }
    if (hpOn) {
      const hpRes = path.join(DATA, "healthprobe-result.json");
      const out2 = { startedAt: new Date().toISOString(), window: 30, samples: [] };
      const save2 = () => { try { fs.writeFileSync(hpRes, JSON.stringify(out2, null, 1)); } catch (e) {} };
      const readCgroup = () => {
        const r = {};
        for (const f of ["/sys/fs/cgroup/cpu.stat", "/sys/fs/cgroup/cpu.max", "/sys/fs/cgroup/cpu.pressure", "/sys/fs/cgroup/memory.current"]) {
          try { r[path.basename(f)] = fs.readFileSync(f, "utf8").trim().split("\n").slice(0, 6).join(" | "); } catch (e) { r[path.basename(f)] = "n/a"; }
        }
        return r;
      };
      const snapProcs = () => {
        const map = {};
        let pids = [];
        try { pids = fs.readdirSync("/proc").filter((n) => /^\d+$/.test(n)); } catch (e) {}
        for (const pid of pids) {
          try {
            const st = fs.readFileSync("/proc/" + pid + "/stat", "utf8");
            const rp = st.lastIndexOf(")");
            const comm = st.slice(st.indexOf("(") + 1, rp);
            const rest = st.slice(rp + 2).split(" ");
            const utime = Number(rest[11]), stime = Number(rest[12]);
            map[pid] = { comm, ticks: (utime || 0) + (stime || 0) };
          } catch (e) {}
        }
        return map;
      };
      try { out2.loadavg = fs.readFileSync("/proc/loadavg", "utf8").trim(); } catch (e) {}
      const t0 = { cgroup: readCgroup(), procs: snapProcs() };
      save2();
      const t = setTimeout(() => {
        const t1 = { cgroup: readCgroup(), procs: snapProcs() };
        const per = [];
        for (const [pid, p1] of Object.entries(t1.procs)) {
          const p0 = t0.procs[pid];
          if (!p0) { per.push({ pid, comm: p1.comm, cpuPct: null, note: "new" }); continue; }
          const d = p1.ticks - p0.ticks;
          per.push({ pid, comm: p1.comm, cpuPct: +(d / 30 / 100 * 100).toFixed(1) });
        }
        per.sort((a, b) => (b.cpuPct || 0) - (a.cpuPct || 0));
        out2.cpu_start = t0.cgroup; out2.cpu_end = t1.cgroup;
        out2.procs = per.slice(0, 15);
        out2.totals = { sumCpuPct: +per.reduce((a, b) => a + (b.cpuPct || 0), 0).toFixed(1) };
        try { out2.loadavgEnd = fs.readFileSync("/proc/loadavg", "utf8").trim(); } catch (e) {}
        out2.finishedAt = new Date().toISOString();
        save2();
        log("[healthprobe] done");
      }, 30000);
      if (t.unref) t.unref();
      log("[healthprobe] sampling for 30s");
    }
  } catch (e) { log("[healthprobe] failed: " + e.message); }
}

// Per-process CPU attribution, enabled by data/cpuattr.json {"on":true}. Starts after boot settles.
if (process.env.SELFTEST !== "1") {
  try {
    const caFlag = path.join(DATA, "cpuattr.json");
    let caOn = false;
    if (fs.existsSync(caFlag)) { try { caOn = !!JSON.parse(fs.readFileSync(caFlag, "utf8") || "{}").on; } catch (e) {} }
    if (caOn) {
      const caRes = path.join(DATA, "cpuattr-result.json");
      const out3 = { startedAt: new Date().toISOString(), window: 30 };
      const save3 = () => { try { fs.writeFileSync(caRes, JSON.stringify(out3, null, 1)); } catch (e) {} };
      const own = () => { try { return fs.readFileSync("/sys/fs/cgroup/cgroup.procs", "utf8").split("\n").map((x) => x.trim()).filter((x) => /^\d+$/.test(x)); } catch (e) { return []; } };
      const snap = () => {
        const m = {};
        for (const pid of own()) {
          try {
            const st = fs.readFileSync("/proc/" + pid + "/stat", "utf8");
            const rp = st.lastIndexOf(")");
            const comm = st.slice(st.indexOf("(") + 1, rp);
            const r = st.slice(rp + 2).split(" ");
            const ticks = Number(r[11] || 0) + Number(r[12] || 0);
            let rss = 0;
            try { rss = Number((fs.readFileSync("/proc/" + pid + "/status", "utf8").match(/^VmRSS:\s*(\d+)/m) || [])[1] || 0); } catch (e) {}
            m[pid] = { comm, ticks, rssMb: Math.round(rss / 1024) };
          } catch (e) {}
        }
        return m;
      };
      const cg = () => { try { return fs.readFileSync("/sys/fs/cgroup/cpu.stat", "utf8").trim().split("\n").map((l) => l.trim()).join(" | "); } catch (e) { return "n/a"; } };
      const t = setTimeout(() => {
        out3.cpuStart = cg(); out3.t0Procs = Object.keys(snap()).length;
        const a = snap();
        setTimeout(() => {
          const b = snap();
          const rows = [];
          let sum = 0;
          for (const pid of Object.keys(b)) {
            const p0 = a[pid]; if (!p0) { rows.push({ pid, comm: b[pid].comm, cpuPct: null }); continue; }
            const pct = +((b[pid].ticks - p0.ticks) / 30 / 100 * 100).toFixed(1);
            sum += pct;
            rows.push({ pid, comm: b[pid].comm, cpuPct: pct, rssMb: b[pid].rssMb });
          }
          rows.sort((x, y) => (y.cpuPct || 0) - (x.cpuPct || 0));
          out3.procs = rows; out3.sumCpuPct = +sum.toFixed(1); out3.cpuEnd = cg();
          out3.finishedAt = new Date().toISOString();
          save3();
          log("[cpuattr] done sum=" + out3.sumCpuPct);
        }, 30000);
      }, 75000);
      if (t.unref) t.unref();
      save3();
      log("[cpuattr] armed (starts in 75s)");
    }
  } catch (e) { log("[cpuattr] failed: " + e.message); }
}
